When sorting strings that can be null or undefined, use a null-safe natural string comparator to prevent calling localeCompare directly on nullish values. This avoids runtime errors and ensures consistent, stable sorting across environments.

```javascript
function normalizedString(value) {
  return value === null || value === undefined ? '' : String(value);
}

function compareNatural(left, right) {
  const s1 = normalizedString(left);
  const s2 = normalizedString(right);
  if (s1 < s2) return -1;
  if (s1 > s2) return 1;
  return 0;
}
```

