The `safeReadJson` function currently only catches JSON parsing errors but does not validate the parsed file shape or check for malformed entries. To prevent runtime property-access errors and ensure the validator fails closed on invalid data, explicitly validate the shape of the parsed JSON and record any malformed entries as structured diagnostics, skipping them from further processing.

```javascript
function safeReadJson(root, relPath, role, diagnostics, validateFn = null) {
  try {
    const data = readJson(root, relPath);
    if (validateFn) {
      const errors = validateFn(data);
      if (errors && errors.length > 0) {
        for (const err of errors) {
          diagnostics.push({
            code: 'malformed_input_entry',
            role,
            path: relPath,
            reason: err,
            severity: 'critical',
          });
        }
        return null;
      }
    }
    return data;
  } catch (error) {
    diagnostics.push({
      code: 'input_file_load_failed',
      role,
      path: relPath,
      reason: error instanceof Error ? error.message : String(error),
      severity: 'critical',
    });
    return null;
  }
}
```

